import React, { useState, useEffect } from 'react';
import { Link, useNavigate } from 'react-router-dom';
import ApiService from '../../Services/ApiService';
import { toast } from 'react-toastify';

export default function SellerReelsAll() {
    const navigate = useNavigate();
    const [reels, setReels] = useState([]);
    const [loading, setLoading] = useState(true);
    const [productNames, setProductNames] = useState({});
    
    // Pagination states
    const [currentPage, setCurrentPage] = useState(1);
    const [itemsPerPage] = useState(10);

    useEffect(() => {
        // Initialize Lucide icons
        if (window.lucide) {
            window.lucide.createIcons();
        }
        
        // Initialize Remix Icons if available
        if (window.RemixIcon) {
            window.RemixIcon.init();
        }
        
        loadSellerReels();
    }, []);

    const loadSellerReels = async () => {
        try {
            setLoading(true);
            
            // Get the vendor ID from the authenticated user
            const user = JSON.parse(localStorage.getItem('studioUser'));
            const vendorId = user?.vendor_id;
            
            if (!vendorId) {
                toast.error('Unable to load reels: User not authenticated');
                setLoading(false);
                return;
            }
            
            // Get seller reels from API
            const response = await ApiService.getSellerReels(vendorId);
            
            if (response.success) {
                // Load product names for all reels
                await loadProductNames(response.data);
                
                // Set reels directly without grouping
                setReels(response.data);
                setCurrentPage(1); // Reset to first page when loading new data
            }
            setLoading(false);
        } catch (error) {
            console.error('Error loading seller reels:', error);
            toast.error('Failed to load reels: ' + error.message);
            setLoading(false);
        }
    };

    // Function to load product names from the database
    const loadProductNames = async (reelsData) => {
        try {
            // Collect all unique product IDs from all reels
            const allProductIds = new Set();
            reelsData.forEach(reel => {
                if (reel.product_ids && Array.isArray(reel.product_ids)) {
                    reel.product_ids.forEach(id => {
                        // Ensure ID is a valid number before adding to set
                        const numericId = parseInt(id);
                        if (!isNaN(numericId) && numericId > 0) {
                            allProductIds.add(numericId);
                        }
                    });
                }
            });

            if (allProductIds.size === 0) {
                setProductNames({});
                return;
            }

            // Convert Set to Array of numbers
            const productIdsArray = Array.from(allProductIds);
            
            // Fetch real product names from the API
            const response = await ApiService.getProductNamesByIds(productIdsArray);
            if (response.success) {
                setProductNames(response.data);
            } else {
                // Fallback to placeholder names if API fails
                const productNamesMap = {};
                productIdsArray.forEach(id => {
                    productNamesMap[id] = `Product ${id}`;
                });
                setProductNames(productNamesMap);
            }
        } catch (error) {
            console.error('Error loading product names:', error);
            // Fallback to placeholder names if API fails
            const allProductIds = new Set();
            reelsData.forEach(reel => {
                if (reel.product_ids && Array.isArray(reel.product_ids)) {
                    reel.product_ids.forEach(id => {
                        const numericId = parseInt(id);
                        if (!isNaN(numericId) && numericId > 0) {
                            allProductIds.add(numericId);
                        }
                    });
                }
            });
            
            const productIdsArray = Array.from(allProductIds);
            const productNamesMap = {};
            productIdsArray.forEach(id => {
                productNamesMap[id] = `Product ${id}`;
            });
            setProductNames(productNamesMap);
        }
    };

    // Function to get product name for a reel
    const getProductNameForReel = (reel) => {
        if (reel.product_ids && Array.isArray(reel.product_ids) && reel.product_ids.length > 0) {
            const productId = parseInt(reel.product_ids[0]);
            if (!isNaN(productId) && productId > 0) {
                return productNames[productId] || `Product ${productId}`;
            }
        }
        return 'No Product Assigned';
    };

    const handleViewReelVideo = async (productId) => {
        // Navigate to the view page for this product
        if (productId) {
            navigate(`/studio/seller/reels/${productId}`);
        } else {
            toast.info('No product associated with these reels');
        }
    };

    const getStatusBadge = (status) => {
        switch (status) {
            case 'approved':
                return <span className="badge bg-success">Approved</span>;
            case 'pending':
                return <span className="badge bg-warning">Pending</span>;
            case 'rejected':
                return <span className="badge bg-danger">Rejected</span>;
            default:
                return <span className="badge bg-secondary">Unknown</span>;
        }
    };

    // Pagination logic
    const indexOfLastItem = currentPage * itemsPerPage;
    const indexOfFirstItem = indexOfLastItem - itemsPerPage;
    const currentReels = reels.slice(indexOfFirstItem, indexOfLastItem);
    const totalPages = Math.ceil(reels.length / itemsPerPage);

    const paginate = (pageNumber) => setCurrentPage(pageNumber);

    return (
        <div className="row">
            <div className="col-12">
                <div className="page-title-box d-flex align-items-center justify-content-between">
                    <h4 className="page-title mb-0">My Reels</h4>
                </div>
            </div>

            <div className="col-12">
                <div className="card">
                    <div className="card-header d-flex align-items-center justify-content-between">
                        <h5 className="card-title mb-0">Reels Management</h5>
                    </div>
                    <div className="card-body">
                        {loading ? (
                            <div className="text-center py-5">
                                <div className="spinner-border" role="status">
                                    <span className="visually-hidden">Loading...</span>
                                </div>
                            </div>
                        ) : reels.length === 0 ? (
                            <div className="text-center py-5">
                                <h5>No reels found</h5>
                                <p className="text-muted">Upload your first reel to get started.</p>
                                <Link to="/studio/seller/upload" className="btn btn-success">
                                    <i className="ri-upload-line me-1"></i> Upload Reel
                                </Link>
                            </div>
                        ) : (
                            <>
                                <div className="table-responsive">
                                    <table className="table table-hover align-middle mb-0">
                                        <thead>
                                            <tr>
                                                <th>Product Name</th>
                                                <th>Reel Count</th>
                                                <th>Title</th>
                                                <th>Category</th>
                                                <th>Status</th>
                                                <th>Views</th>
                                                <th>Likes</th>
                                                <th>Date</th>
                                                <th>Actions</th>
                                            </tr>
                                        </thead>
                                        <tbody>
                                            {currentReels.map((reel) => (
                                                <tr key={reel.id}>
                                                    <td>{getProductNameForReel(reel)}</td>
                                                    <td>
                                                        <span className="badge bg-primary">
                                                            {reel.product_ids && Array.isArray(reel.product_ids) ? reel.product_ids.length : 0}
                                                        </span>
                                                    </td>
                                                    <td>{reel.title}</td>
                                                    <td>{reel.category_name || 'N/A'}</td>
                                                    <td>{getStatusBadge(reel.status)}</td>
                                                    <td>{reel.views || 0}</td>
                                                    <td>{reel.likes || 0}</td>
                                                    <td>{reel.created_at ? new Date(reel.created_at).toLocaleDateString() : 'N/A'}</td>
                                                    <td>
                                                        <button 
                                                            className="btn btn-sm btn-info"
                                                            onClick={() => handleViewReelVideo(reel.product_ids && reel.product_ids.length > 0 ? parseInt(reel.product_ids[0]) : null)}
                                                            title="View Reels"
                                                            disabled={!reel.product_ids || reel.product_ids.length === 0}
                                                        >
                                                            <i className="ri-eye-line"></i> View
                                                        </button>
                                                    </td>
                                                </tr>
                                            ))}
                                        </tbody>
                                    </table>
                                </div>
                                
                                {/* Pagination */}
                                {totalPages > 1 && (
                                    <nav aria-label="Reels pagination" className="mt-4">
                                        <ul className="pagination justify-content-center">
                                            <li className={`page-item ${currentPage === 1 ? 'disabled' : ''}`}>
                                                <button 
                                                    className="page-link" 
                                                    onClick={() => paginate(currentPage - 1)}
                                                    disabled={currentPage === 1}
                                                >
                                                    Previous
                                                </button>
                                            </li>
                                            
                                            {[...Array(totalPages)].map((_, index) => {
                                                const pageNumber = index + 1;
                                                return (
                                                    <li 
                                                        key={pageNumber} 
                                                        className={`page-item ${currentPage === pageNumber ? 'active' : ''}`}
                                                    >
                                                        <button 
                                                            className="page-link" 
                                                            onClick={() => paginate(pageNumber)}
                                                        >
                                                            {pageNumber}
                                                        </button>
                                                    </li>
                                                );
                                            })}
                                            
                                            <li className={`page-item ${currentPage === totalPages ? 'disabled' : ''}`}>
                                                <button 
                                                    className="page-link" 
                                                    onClick={() => paginate(currentPage + 1)}
                                                    disabled={currentPage === totalPages}
                                                >
                                                    Next
                                                </button>
                                            </li>
                                        </ul>
                                    </nav>
                                )}
                            </>
                        )}
                    </div>
                </div>
            </div>
        </div>
    );
}
